head.script:
// 테스트 설명, 유효성 값 설정
//  ★ iframe 컴포넌트는 읽기 전용(readonly)을 실질적으로 지원하지 않는다.
//    - setReadOnly 는 no-op(@hidden) 이며, readonly="true" 로 생성해도 미파싱되어 getReadOnly 는 항상 false 를 반환한다.
//    - 따라서 본 샘플은 "초기 로딩 후 getReadOnly() 가 false 를 반환하는 것"만 검증한다.
//  ★ iframe 컴포넌트 자체는 onclick 이벤트를 지원하지 않으나(oniframeload / oniframeunload 만 지원),
//    별도 w2:button 의 onclick 으로 target1.getReadOnly() 를 호출하는 것은 정상이다(버튼은 별도 컴포넌트).
//  · iframe 은 dynamicCreate 시 inline src 를 주면 _dynamicCreateAfter 가 미로딩 contentDocument 접근으로 TypeError.
//    → src 없이 생성 후 setSrc() 로 내부 페이지를 설정한다. (reference_iframe_dynamic_setsrc_not_inline)
scwin.tData = {
    "description" : "[iframe > M > getReadOnly]<br/>컴포넌트에 적용된 읽기 전용(readonly) 상태값을 반환합니다.",
    "validation" : [
        "읽기 전용(readonly) 상태인 경우 true 로 반환하여야 합니다.",
        "읽기 전용(readonly) 해제 상태인 경우 false 로 반환하여야 합니다."
    ]
}



scwin.onpageload = async function () {
    // comp 초기 생성 (비동기 dynamicCreate / setSrc 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] iframe 컴포넌트는 읽기 전용(readonly)을 실질적으로 지원하지 않습니다. 본 샘플은 getReadOnly() 가 초기 로딩 후 false 를 반환하는 것만 검증합니다."', '', 'label1');

    // iframe(target1) 생성 : inline src 금지 → helper 내부에서 dynamicCreate 후 setSrc 처리(내용 표시)
    await $c.gcm.createBasicIframe();
}



// [getReadOnly] 버튼 클릭 : iframe 의 읽기 전용 상태값을 결과창에 출력
//  - createBasicIframe 이 생성한 iframe 은 컴포넌트 id 로 참조한다(target1).
//    (helper 는 공통모듈 scwin 에 대입하므로 샘플 scwin.target1 이 아닌 엔진의 id 참조 target1 을 사용)
//  - iframe 은 readonly 를 지원하지 않으므로 반환값은 항상 false 이다.
scwin.btn_getReadOnly_onclick = function (e) {
    let rtn = target1.getReadOnly();
    wf_body_bottom.getObj("scwin").setReturnValue("getReadOnly() 반환값 : " + rtn);
};
